import java.util.*;

public class Main {
    static String[] mapping = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
    static List<String> result;

    static List<String> letterCombinations(String digits) {
        result = new ArrayList<>();
        if (digits.isEmpty()) return result;
        backtrack(digits, 0, new StringBuilder());
        return result;
    }

    static void backtrack(String digits, int index, StringBuilder current) {
        if (index == digits.length()) {
            result.add(current.toString());                  // base case: full combination built
            return;
        }
        String letters = mapping[digits.charAt(index) - '0'];
        for (char letter : letters.toCharArray()) {
            current.append(letter);
            backtrack(digits, index + 1, current);            // try each letter, recurse
            current.deleteCharAt(current.length() - 1);       // undo
        }
    }
}

